'use client'

import { useState, useMemo, useEffect } from 'react'
import { TransactionWithDetails, Account, Category, Person, Shop } from '@/types/moneyflow.types'
import { resolveTransactionCycleTag } from '@/lib/cycle-utils'
import { cn } from '@/lib/utils'
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '@/components/ui/card'
import { Badge } from '@/components/ui/badge'
import { 
    Coins, 
    Gift, 
    TrendingUp, 
    PieChart, 
    Calendar,
    ChevronRight,
    ChevronLeft,
    Search,
    Filter,
    ArrowUpRight,
    ArrowDownLeft,
    Banknote,
    Receipt,
    History
} from 'lucide-react'
import { format, parseISO } from 'date-fns'

const currencyFormatter = new Intl.NumberFormat('vi-VN', {
    maximumFractionDigits: 0,
})

interface AccountDetailCashbackProps {
    account: Account
    transactions: TransactionWithDetails[]
    categories: Category[]
    people: Person[]
    shops: Shop[]
}

export function AccountDetailCashback({
    account,
    transactions,
    categories,
    people,
    shops
}: AccountDetailCashbackProps) {
    const [selectedCycle, setSelectedCycle] = useState<string>('all')
    const [searchTerm, setSearchTerm] = useState('')

    // Extract available cycles
    const availableCycles = useMemo(() => {
        const cycles = new Set<string>()
        transactions.forEach(t => {
            const tag = resolveTransactionCycleTag(t, account)
            if (tag) cycles.add(tag)
        })
        return Array.from(cycles).sort((a, b) => b.localeCompare(a))
    }, [transactions, account])

    // Filter transactions to only those with cashback or relevant to selected cycle
    const filteredTransactions = useMemo(() => {
        let result = transactions.filter(t => {
            if (t.status === 'void') return false
            
            // Show if it has cashback entries or share or final_price < amount
            const hasCashback = (t.cashback_entries && Array.isArray(t.cashback_entries) && t.cashback_entries.length > 0) ||
                (Number(t.cashback_share_amount || 0) > 0) ||
                (Number(t.cashback_share_percent || 0) > 0) ||
                (t.final_price !== null && Math.abs(Number(t.final_price)) < Math.abs(Number(t.amount)))

            if (!hasCashback) return false

            if (selectedCycle !== 'all') {
                return resolveTransactionCycleTag(t, account) === selectedCycle
            }
            return true
        })

        if (searchTerm) {
            const term = searchTerm.toLowerCase()
            result = result.filter(t => 
                t.note?.toLowerCase().includes(term) ||
                t.shop_name?.toLowerCase().includes(term) ||
                t.category_name?.toLowerCase().includes(term)
            )
        }

        return result.sort((a, b) => new Date(b.occurred_at || b.created_at).getTime() - new Date(a.occurred_at || a.created_at).getTime())
    }, [transactions, selectedCycle, searchTerm, account])

    // Calculate stats
    const stats = useMemo(() => {
        let totalEarned = 0
        let totalShared = 0
        let totalSpent = 0

        filteredTransactions.forEach(t => {
            const amount = Math.abs(Number(t.amount || 0))
            totalSpent += amount

            // Earned from bank
            const entries = Array.isArray(t.cashback_entries) ? t.cashback_entries : []
            const entryAmount = entries.reduce((s: number, e: any) => {
                if (e.mode === "virtual" || e.mode === "real") {
                    return s + Math.abs(Number(e.amount || 0))
                }
                return s
            }, 0)

            if (entryAmount > 0) {
                totalEarned += entryAmount
            } else {
                const finalPrice = t.final_price !== null ? Math.abs(Number(t.final_price)) : amount
                totalEarned += Math.max(0, amount - finalPrice)
            }

            // Shared with others
            totalShared += Number(t.cashback_share_amount || 0)
        })

        const netProfit = totalEarned - totalShared

        return {
            totalEarned,
            totalShared,
            totalSpent,
            netProfit,
            count: filteredTransactions.length
        }
    }, [filteredTransactions])

    return (
        <div className="space-y-6 animate-in fade-in slide-in-from-bottom-4 duration-500">
            {/* Stats Overview */}
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
                <Card className="bg-white/50 backdrop-blur-sm border-slate-200/60 shadow-sm hover:shadow-md transition-all">
                    <CardHeader className="pb-2 flex flex-row items-center justify-between space-y-0">
                        <CardTitle className="text-sm font-medium text-slate-500">Total Earned (Bank)</CardTitle>
                        <div className="p-2 bg-emerald-100 rounded-lg">
                            <Coins className="h-4 w-4 text-emerald-600" />
                        </div>
                    </CardHeader>
                    <CardContent>
                        <div className="text-2xl font-bold text-emerald-600">{currencyFormatter.format(stats.totalEarned)}</div>
                        <p className="text-xs text-slate-400 mt-1">From {stats.count} transactions</p>
                    </CardContent>
                </Card>

                <Card className="bg-white/50 backdrop-blur-sm border-slate-200/60 shadow-sm hover:shadow-md transition-all">
                    <CardHeader className="pb-2 flex flex-row items-center justify-between space-y-0">
                        <CardTitle className="text-sm font-medium text-slate-500">Shared with Others</CardTitle>
                        <div className="p-2 bg-amber-100 rounded-lg">
                            <Banknote className="h-4 w-4 text-amber-600" />
                        </div>
                    </CardHeader>
                    <CardContent>
                        <div className="text-2xl font-bold text-slate-700">{currencyFormatter.format(stats.totalShared)}</div>
                        <p className="text-xs text-slate-400 mt-1">Allocated to people</p>
                    </CardContent>
                </Card>

                <Card className="bg-white/50 backdrop-blur-sm border-slate-200/60 shadow-sm hover:shadow-md transition-all">
                    <CardHeader className="pb-2 flex flex-row items-center justify-between space-y-0">
                        <CardTitle className="text-sm font-medium text-slate-500">Net Profit</CardTitle>
                        <div className="p-2 bg-blue-100 rounded-lg">
                            <TrendingUp className="h-4 w-4 text-blue-600" />
                        </div>
                    </CardHeader>
                    <CardContent>
                        <div className={cn(
                            "text-2xl font-bold",
                            stats.netProfit >= 0 ? "text-blue-600" : "text-rose-600"
                        )}>
                            {currencyFormatter.format(stats.netProfit)}
                        </div>
                        <p className="text-xs text-slate-400 mt-1">Total benefit retained</p>
                    </CardContent>
                </Card>

                <Card className="bg-white/50 backdrop-blur-sm border-slate-200/60 shadow-sm hover:shadow-md transition-all">
                    <CardHeader className="pb-2 flex flex-row items-center justify-between space-y-0">
                        <CardTitle className="text-sm font-medium text-slate-500">Avg. Saving Rate</CardTitle>
                        <div className="p-2 bg-indigo-100 rounded-lg">
                            <PieChart className="h-4 w-4 text-indigo-600" />
                        </div>
                    </CardHeader>
                    <CardContent>
                        <div className="text-2xl font-bold text-slate-700">
                            {stats.totalSpent > 0 ? ((stats.totalEarned / stats.totalSpent) * 100).toFixed(1) : '0'}%
                        </div>
                        <p className="text-xs text-slate-400 mt-1">Based on spending</p>
                    </CardContent>
                </Card>
            </div>

            {/* Filters & List */}
            <div className="bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden min-h-[400px]">
                <div className="p-4 border-b border-slate-100 bg-slate-50/50 flex flex-wrap items-center gap-4">
                    <div className="relative flex-1 min-w-[240px]">
                        <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-slate-400" />
                        <input
                            type="text"
                            placeholder="Search cashback transactions..."
                            className="w-full pl-10 pr-4 py-2 bg-white border border-slate-200 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-blue-500/20 focus:border-blue-500 transition-all"
                            value={searchTerm}
                            onChange={(e) => setSearchTerm(e.target.value)}
                        />
                    </div>

                    <div className="flex items-center gap-2">
                        <Calendar className="h-4 w-4 text-slate-400" />
                        <select
                            className="bg-white border border-slate-200 rounded-lg text-sm px-3 py-2 focus:outline-none focus:ring-2 focus:ring-blue-500/20 focus:border-blue-500 transition-all outline-none"
                            value={selectedCycle}
                            onChange={(e) => setSelectedCycle(e.target.value)}
                        >
                            <option value="all">All Cycles</option>
                            {availableCycles.map(c => (
                                <option key={c} value={c}>{c}</option>
                            ))}
                        </select>
                    </div>
                </div>

                <div className="overflow-x-auto">
                    <table className="w-full text-sm text-left border-collapse">
                        <thead className="bg-slate-50/50 text-slate-500 font-medium border-b border-slate-100">
                            <tr>
                                <th className="px-6 py-3 font-semibold text-[11px] uppercase tracking-wider">Date / Shop</th>
                                <th className="px-6 py-3 font-semibold text-[11px] uppercase tracking-wider text-right">Amount</th>
                                <th className="px-6 py-3 font-semibold text-[11px] uppercase tracking-wider text-right">Bank Back</th>
                                <th className="px-6 py-3 font-semibold text-[11px] uppercase tracking-wider text-right">Shared</th>
                                <th className="px-6 py-3 font-semibold text-[11px] uppercase tracking-wider text-right">Profit</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-slate-50">
                            {filteredTransactions.length === 0 ? (
                                <tr>
                                    <td colSpan={5} className="px-6 py-20 text-center text-slate-400">
                                        <div className="flex flex-col items-center gap-2">
                                            <History className="h-10 w-10 opacity-20" />
                                            <p>No cashback transactions found matching criteria</p>
                                        </div>
                                    </td>
                                </tr>
                            ) : (
                                filteredTransactions.map((txn) => {
                                    const { earned, shared } = (() => {
                                        const amount = Math.abs(Number(txn.amount || 0))
                                        const entries = Array.isArray(txn.cashback_entries) ? txn.cashback_entries : []
                                        const entryAmount = entries.reduce((s: number, e: any) => {
                                            if (e.mode === "virtual" || e.mode === "real") return s + Math.abs(Number(e.amount || 0))
                                            return s
                                        }, 0)
                                        
                                        let earned = 0
                                        if (entryAmount > 0) {
                                            earned = entryAmount
                                        } else {
                                            const finalPrice = txn.final_price !== null ? Math.abs(Number(txn.final_price)) : amount
                                            earned = Math.max(0, amount - finalPrice)
                                        }
                                        
                                        return { earned, shared: Number(txn.cashback_share_amount || 0) }
                                    })()

                                    const profit = earned - shared

                                    return (
                                        <tr key={txn.id} className="hover:bg-slate-50/50 transition-colors group cursor-default">
                                            <td className="px-6 py-4">
                                                <div className="flex flex-col">
                                                    <span className="font-medium text-slate-900">{txn.occurred_at ? format(parseISO(txn.occurred_at), 'dd/MM/yyyy') : '--'}</span>
                                                    <span className="text-slate-500 text-xs truncate max-w-[200px]">{txn.shop_name || txn.note || 'No description'}</span>
                                                </div>
                                            </td>
                                            <td className="px-6 py-4 text-right font-medium text-slate-700">
                                                {currencyFormatter.format(Math.abs(Number(txn.amount)))}
                                            </td>
                                            <td className="px-6 py-4 text-right">
                                                <span className="text-emerald-600 font-semibold">+{currencyFormatter.format(earned)}</span>
                                            </td>
                                            <td className="px-6 py-4 text-right">
                                                {shared > 0 ? (
                                                    <span className="text-amber-600">-{currencyFormatter.format(shared)}</span>
                                                ) : <span className="text-slate-300">-</span>}
                                            </td>
                                            <td className="px-6 py-4 text-right">
                                                <Badge variant="outline" className={cn(
                                                    "font-bold",
                                                    profit >= 0 ? "bg-blue-50 text-blue-700 border-blue-200" : "bg-rose-50 text-rose-700 border-rose-200"
                                                )}>
                                                    {currencyFormatter.format(profit)}
                                                </Badge>
                                            </td>
                                        </tr>
                                    )
                                })
                            )}
                        </tbody>
                    </table>
                </div>
            </div>
        </div>
    )
}
